import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';
import { loadStripe } from '@stripe/stripe-js';
import stripeService from '../../services/stripeService';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

const Torneos = () => {
  const { user, checkStripeOnboarding, getStripeOnboardingLink } = useAuth();
  const [torneos, setTorneos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [mensaje, setMensaje] = useState(null);
  const [onboardingComplete, setOnboardingComplete] = useState(false);

  useEffect(() => {
    cargarTorneos();
    verificarOnboarding();
  }, [user]);

  const verificarOnboarding = async () => {
    if (user) {
      const completed = await checkStripeOnboarding();
      setOnboardingComplete(completed);
    }
  };

  const cargarTorneos = async () => {
    try {
      // Torneos en MXN
      const torneosSimulados = [
        {
          id: 'torneo_001',
          nombre: 'Torneo de Derecho Civil 2026',
          descripcion: 'Demuestra tus conocimientos en Derecho Civil',
          fecha: '2026-06-15',
          costo_inscripcion: 1900,
          premio_acumulado: 95000,
          estado: 'abierto',
          participantes_actuales: 45,
          cupo_maximo: 100
        },
        {
          id: 'torneo_002',
          nombre: 'Torneo de Derecho Penal 2026',
          descripcion: 'Competencia de litigio penal',
          fecha: '2026-07-20',
          costo_inscripcion: 2850,
          premio_acumulado: 190000,
          estado: 'abierto',
          participantes_actuales: 32,
          cupo_maximo: 80
        }
      ];
      setTorneos(torneosSimulados);
    } catch (error) {
      console.error('Error cargando torneos:', error);
      setMensaje({ type: 'error', text: error.message });
    } finally {
      setLoading(false);
    }
  };

  const handleVerificarIdentidad = async () => {
    setProcessing(true);
    try {
      const link = await getStripeOnboardingLink();
      if (link) {
        window.location.href = link;
      } else {
        setMensaje({ 
          type: 'error', 
          text: 'No se pudo generar el link de verificación. Contacta a soporte.' 
        });
      }
    } catch (error) {
      setMensaje({ type: 'error', text: error.message });
    } finally {
      setProcessing(false);
    }
  };

  const handleInscribirse = async (torneo) => {
    if (!user) {
      setMensaje({ type: 'warning', text: 'Debes iniciar sesión para inscribirte' });
      return;
    }

    if (!onboardingComplete) {
      setMensaje({ 
        type: 'warning', 
        text: 'Debes completar la verificación de identidad en Stripe antes de participar en torneos.' 
      });
      return;
    }

    setProcessing(true);
    setMensaje(null);

    try {
      // Crear PaymentIntent en MXN
      const paymentIntent = await stripeService.createPaymentIntent(
        torneo.costo_inscripcion,
        'mxn',
        { tournament_id: torneo.id, type: 'tournament_registration', tournament_name: torneo.nombre }
      );

      const stripe = await stripePromise;
      const { error } = await stripe.confirmPayment({
        clientSecret: paymentIntent.clientSecret,
        confirmParams: {
          return_url: `${window.location.origin}/torneos/${torneo.id}/confirmacion`,
        },
      });

      if (error) {
        throw new Error(error.message);
      }
      
    } catch (error) {
      console.error('Error en inscripción:', error);
      setMensaje({ type: 'error', text: error.message });
    } finally {
      setProcessing(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-gray-500">Cargando torneos...</div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold text-gray-800 mb-6">🏆 Torneos Jurídicos Lex Mundi</h1>
      
      {/* Banner de verificación de identidad */}
      {user && !onboardingComplete && (
        <div className="bg-amber-50 border-l-4 border-amber-500 rounded-lg p-4 mb-6 shadow-sm">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div className="flex items-start">
              <div className="flex-shrink-0">
                <span className="text-amber-600 text-2xl">⚠️</span>
              </div>
              <div className="ml-3">
                <h3 className="text-base font-semibold text-amber-800">Verificación de identidad requerida</h3>
                <p className="text-sm text-amber-700 mt-1 max-w-2xl">
                  Para participar en torneos y recibir premios en efectivo, necesitas verificar tu identidad en Stripe. 
                  Es un proceso rápido y seguro que solo tomará 2 minutos.
                </p>
                <p className="text-xs text-amber-600 mt-1">
                  ✅ Stripe es una plataforma segura y verificada a nivel mundial.
                </p>
              </div>
            </div>
            <button
              onClick={handleVerificarIdentidad}
              disabled={processing}
              className="bg-amber-600 text-white px-5 py-2 rounded-lg text-sm font-semibold hover:bg-amber-700 transition-colors whitespace-nowrap disabled:opacity-50"
            >
              {processing ? 'Procesando...' : 'Verificar mi identidad ahora'}
            </button>
          </div>
        </div>
      )}
      
      {/* Mensaje de estado */}
      {mensaje && (
        <div className={`p-4 rounded-lg mb-6 ${
          mensaje.type === 'success' ? 'bg-green-100 text-green-700 border border-green-300' :
          mensaje.type === 'warning' ? 'bg-yellow-100 text-yellow-700 border border-yellow-300' :
          'bg-red-100 text-red-700 border border-red-300'
        }`}>
          {mensaje.text}
        </div>
      )}
      
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {torneos.map((torneo) => (
          <div key={torneo.id} className="bg-white rounded-xl shadow-lg overflow-hidden hover:shadow-xl transition-shadow">
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <h2 className="text-xl font-bold text-gray-800">{torneo.nombre}</h2>
                <span className="bg-green-100 text-green-800 text-sm font-medium px-2.5 py-0.5 rounded">
                  {torneo.estado === 'abierto' ? 'Abierto' : 'Cerrado'}
                </span>
              </div>
              
              <p className="text-gray-600 mb-4">{torneo.descripcion}</p>
              
              <div className="space-y-2 mb-4">
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500">📅 Fecha:</span>
                  <span className="font-medium">{new Date(torneo.fecha).toLocaleDateString('es-MX')}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500">💰 Premio acumulado:</span>
                  <span className="font-bold text-green-600">${torneo.premio_acumulado.toLocaleString('es-MX')} MXN</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-gray-500">🎯 Cupo:</span>
                  <span className="font-medium">{torneo.participantes_actuales || 0} / {torneo.cupo_maximo}</span>
                </div>
              </div>
              
              <button
                onClick={() => handleInscribirse(torneo)}
                disabled={processing || torneo.estado !== 'abierto' || (torneo.participantes_actuales >= torneo.cupo_maximo) || !onboardingComplete}
                className={`w-full py-2 px-4 rounded-lg font-semibold transition-colors ${
                  torneo.estado === 'abierto' && torneo.participantes_actuales < torneo.cupo_maximo && onboardingComplete
                    ? 'bg-blue-600 text-white hover:bg-blue-700'
                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
              >
                {processing ? 'Procesando...' : (
                  torneo.estado === 'abierto' 
                    ? torneo.participantes_actuales >= torneo.cupo_maximo 
                      ? 'Cupo lleno' 
                      : `Inscribirse - $${torneo.costo_inscripcion.toLocaleString('es-MX')} MXN`
                    : 'Torneo cerrado'
                )}
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Torneos;
